package org.systemmaster.tools.ocr;
import javax.imageio.ImageIO;import java.awt.*;import java.awt.image.*;import java.io.*;import java.nio.file.*;import java.time.Duration;import java.util.Map;
public final class OcrTesseractQualification {static int n;public static void main(String[]a)throws Exception{if(a.length!=1)throw new IllegalArgumentException("tesseract path required");BufferedImage img=new BufferedImage(500,100,BufferedImage.TYPE_INT_RGB);for(int y=0;y<100;y++)for(int x=0;x<500;x++)img.setRGB(x,y,Color.WHITE.getRGB());Graphics2D g=img.createGraphics();g.setColor(Color.BLACK);g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,32));g.drawString("SYSTEM MASTER OCR 2026",15,55);g.dispose();ByteArrayOutputStream bo=new ByteArrayOutputStream();ImageIO.write(img,"png",bo);var p=new TesseractOcrEnginePort(Path.of(a[0]),Duration.ofSeconds(30),"eng");var svc=new OcrFullLaneService();var graph=svc.recognize(p,bo.toByteArray(),"ocr.run.recognize",Map.of());check(!graph.regions().isEmpty(),"recognized regions");String joined=graph.regions().stream().map(OcrFullLaneEngine.CanonicalRegion::text).reduce("",(x,y)->x+" "+y).toUpperCase();check(joined.contains("SYSTEM")&&joined.contains("MASTER"),"expected text");check(graph.regions().stream().allMatch(r->r.engineId().equals("TESSERACT")),"engine identity bound");System.out.println("OCR_TESSERACT_QUALIFICATION_PASS assertions="+n+" words="+graph.regions().size()+" version="+p.identity().version());}static void check(boolean c,String m){n++;if(!c)throw new AssertionError(m);}}
